"use client";

import React from "react";
import useTypewriterEffect, {
    UseTypewriterOptions,
} from "../hooks/useTypewriterEffect.hooks";

type TypewriterProps = React.HTMLAttributes<HTMLParagraphElement> & {
    text: string;
    options: Omit<UseTypewriterOptions, "text">;
};

/**
 * Typewriter text animation component.
 *
 * @param {string} text - The text to animate
 * @param {Omit<UseTypewriterOptions, 'text'>} options - Typewriter animation options
 * @param {React.HTMLAttributes<HTMLParagraphElement>} props - Additional HTML paragraph attributes
 *
 * @example
 * ```tsx
 * <Typewriter
 *   text="Hello, World!"
 *   options={{
 *     startDelay: 250,
 *     minDelayMs: 75,
 *     maxDelayMs: 300,
 *   }}
 * />
 * ```
 */
function Typewriter({ text, options, ...props }: TypewriterProps) {
    const typewriter = useTypewriterEffect({
        text,
        options: {
            ...options,
        },
    });

    return (
        <p
            data-is-paused={typewriter.isPaused}
            data-running={!typewriter.isPaused && !typewriter.isComplete}
            data-reversing={typewriter.isReversing}
            data-complete={typewriter.isComplete}
            {...props}
        >
            {typewriter.text}
        </p>
    );
}

Typewriter.displayName = "Typewriter";
export default Typewriter;

import "@/components/ui/typewriter/css/cursorBlink.typeWriter.css";
import { cn } from "@/lib/tools/cn.tools";

type AnimatedCursorProps = React.HTMLAttributes<HTMLSpanElement> & {
    options?: {
        isBlinking: boolean;
        isVisible: boolean;
        cursor: string;
    };
};

const defaultCursorOptions = {
    isBlinking: true,
    isVisible: true,
    cursor: "|",
};

/**
 * Animated cursor component for typewriter effects.
 *
 * @param {Object} options - Cursor animation options
 * @param {React.HTMLAttributes<HTMLSpanElement>} props - Additional HTML span attributes
 *
 * @example
 * <AnimatedCursor cursor="_" isBlinking={true} />
 */
function AnimatedCursor({
    options = defaultCursorOptions,
    className,
    ...props
}: AnimatedCursorProps) {
    const { isBlinking, isVisible, cursor } = options;
    return (
        <span
            className={cn(
                "inline-block w-[1ch]",
                isBlinking && "animate-[cursor-blink_1s_steps(1)_infinite]",
                !isVisible && "opacity-0",
                className,
            )}
            data-blinking={isBlinking}
            data-visible={isVisible}
            aria-hidden="true"
            {...props}
        >
            {isVisible ? cursor : ""}
        </span>
    );
}

AnimatedCursor.displayName = "AnimatedCursor";

export { type AnimatedCursorProps, AnimatedCursor };

"use client";

import { useEffect, useState, useRef, useCallback } from "react";

interface UseTypewriterOptions {
    startDelay?: number;
    minDelayMs?: number;
    maxDelayMs?: number;
    completionPause?: number;
    isReversing?: boolean;
    loop?: boolean;
    isPaused?: boolean;
}

const DEFAULT_OPTIONS: UseTypewriterOptions = {
    startDelay: 250,
    minDelayMs: 75,
    maxDelayMs: 300,
    completionPause: 3000,
    isReversing: false,
    loop: false,
    isPaused: false,
};

interface TypewriterState {
    currentText: string;
    isReversing: boolean;
    isComplete: boolean;
}

interface UseTypeWriterProps {
    text: string;
    options?: UseTypewriterOptions;
}

/**
 * Hook that creates a typewriter effect for text.
 *
 * @param options - Configuration options for the typewriter effect
 * @param options.text - Text to type out
 * @param options.startDelay - Delay before typing starts (ms, default: 250)
 * @param options.minDelay - Minimum delay between characters (ms, default: 75)
 * @param options.maxDelay - Maximum delay between characters (ms, default: 300)
 * @param options.completionPause - Pause duration when typing completes before looping (ms, default: 3000)
 * @param options.isReversing - Start in reverse mode/deleting (default: false)
 * @param options.loop - Loop the typing animation (default: false)
 * @param options.isPaused - Pause the animation (default: false)
 *
 * @returns Typewriter state and controls
 * @returns text - The current text being displayed (partially typed)
 * @returns isComplete - Whether the typing animation has completed
 * @returns isReversing - Whether currently in reverse/deletion mode
 * @returns isPaused - Whether the animation is currently paused
 * @returns reset - Function to reset the typewriter to initial state, optionally specify reverse mode
 *
 * @example
 * const typewriter = useTypewriterEffect({
 *   text: "Hello, World!",
 *   loop: true,
 *   minDelay: 50,
 *   maxDelay: 150,
 * });
 *
 * return (
 *   <div>
 *     <p>{typewriter.text}</p>
 *     <button onClick={() => typewriter.reset()}>Reset</button>
 *   </div>
 * );
 */
function useTypewriterEffect({
    text,
    options = DEFAULT_OPTIONS,
}: UseTypeWriterProps) {
    const {
        startDelay,
        minDelayMs,
        maxDelayMs,
        completionPause,
        isReversing,
        loop,
        isPaused,
    } = options;

    const [state, setState] = useState<TypewriterState>({
        currentText: isReversing ? text : "",
        isReversing: isReversing!,
        isComplete: false,
    });

    const timerRef = useRef<number | null>(null);

    // Store config in refs to avoid effect re-runs
    const configRef = useRef({
        startDelay,
        minDelayMs,
        maxDelayMs,
        completionPause,
        loop,
    });

    // Update config ref when values change
    useEffect(() => {
        configRef.current = {
            startDelay,
            minDelayMs,
            maxDelayMs,
            completionPause,
            loop,
        };
    }, [startDelay, minDelayMs, maxDelayMs, completionPause, loop]);

    useEffect(() => {
        if (!text || text.length === 0 || isPaused) return;

        const config = configRef.current;
        const atInitialStart =
            (!state.isReversing && state.currentText.length === 0) ||
            (state.isReversing && state.currentText.length === text.length);

        // Calculate delay
        let delay = config.startDelay;
        if (state.isComplete) {
            delay = config.completionPause;
        } else if (!atInitialStart) {
            delay =
                Math.floor(
                    Math.random() * (config.maxDelayMs! - config.minDelayMs! + 1),
                ) + config.minDelayMs!;
        }

        timerRef.current = window.setTimeout(() => {
            setState((prev) => {
                // Handle completion and looping
                if (prev.isComplete) {
                    if (!config.loop) return prev;

                    const nextIsReversing = !prev.isReversing;
                    return {
                        isComplete: false,
                        isReversing: nextIsReversing,
                        currentText: nextIsReversing ? text : "",
                    };
                }

                // Forward typing
                if (!prev.isReversing) {
                    const nextText = text.slice(0, prev.currentText.length + 1);
                    const done = nextText.length === text.length;
                    return {
                        ...prev,
                        currentText: nextText,
                        isComplete: done,
                    };
                }

                // Reverse typing
                const nextText = prev.currentText.slice(0, -1);
                const done = nextText.length === 0;
                return {
                    ...prev,
                    currentText: nextText,
                    isComplete: done,
                };
            });
        }, delay);

        return () => {
            if (timerRef.current !== null) {
                clearTimeout(timerRef.current);
                timerRef.current = null;
            }
        };
    }, [
        text,
        state.currentText,
        state.isReversing,
        state.isComplete,
        isPaused,
    ]);

    const reset = useCallback(
        (resetToReverse: boolean = isReversing!) => {
            if (timerRef.current !== null) {
                clearTimeout(timerRef.current);
                timerRef.current = null;
            }
            setState({
                currentText: resetToReverse ? text : "",
                isReversing: resetToReverse,
                isComplete: false,
            });
        },
        [text, isReversing],
    );

    return {
        text: state.currentText,
        isComplete: state.isComplete,
        isReversing: state.isReversing,
        isPaused: isPaused,
        reset,
    };
}

useTypewriterEffect.displayName = "useTypewriterEffect";

export { type UseTypewriterOptions, type TypewriterState };
export default useTypewriterEffect;
